with valid as (select id, device_code, temp_c, humidity, status_bits, greatest(status_bits, pressure) as greatest_status_bits_pressure from device_readings where reading_ts > timestamp '2025-09-01 06:00:00' and humidity is null), cleaned as (select id, humidity, status_bits, greatest_status_bits_pressure, humidity / nullif(greatest_status_bits_pressure, 0) as humidity_per_greatest_status_bits_pressure, greatest(status_bits, humidity) as greatest_status_bits_humidity from valid where greatest_status_bits_pressure between 57 and 64), valid_device_readings as (select *, floor(humidity) as humidity_whole, status_bits + greatest_status_bits_humidity as status_bits_plus_greatest_status_bits_humidity from cleaned where humidity_per_greatest_status_bits_pressure is null), base as (select id, greatest_status_bits_humidity, humidity_whole, status_bits_plus_greatest_status_bits_humidity, ceil(humidity_per_greatest_status_bits_pressure) as humidity_per_greatest_status_bits_pressure_whole from valid_device_readings where greatest_status_bits_humidity between 66 and 71), filtered as (select id, humidity_whole, status_bits_plus_greatest_status_bits_humidity, humidity_per_greatest_status_bits_pressure_whole, round(humidity_whole, 0) as humidity_whole_rounded, humidity_whole - greatest_status_bits_humidity as humidity_whole_minus_greatest_status_bits_humidity from base where status_bits_plus_greatest_status_bits_humidity is null), cleaned_device_readings as (select id, humidity_whole, status_bits_plus_greatest_status_bits_humidity, humidity_per_greatest_status_bits_pressure_whole, humidity_whole_rounded, case when status_bits_plus_greatest_status_bits_humidity >= 89 then 'High' when status_bits_plus_greatest_status_bits_humidity >= 27 then 'Medium' else 'Low' end as status_bits_plus_greatest_status_bits_humidity_level from filtered where status_bits_plus_greatest_status_bits_humidity > 32), base_device_readings as (select id, humidity_whole, status_bits_plus_greatest_status_bits_humidity, humidity_whole_rounded, status_bits_plus_greatest_status_bits_humidity_level, humidity_whole_rounded - humidity_whole as humidity_whole_rounded_minus_humidity_whole from cleaned_device_readings where humidity_whole_rounded >= 48) select id, humidity_whole, status_bits_plus_greatest_status_bits_humidity, humidity_whole_rounded, humidity_whole_rounded_minus_humidity_whole from base_device_readings;
